            + abz*g1(101) &
            + cdz*g1(21) &
            + g1(114)
         vbuf(87) = abx*abz*cdz*g1(3) &
            + abx*abz*g1(96) &
            + abx*cdz*g1(12) &
            + abx*g1(105) &
            + abz*cdz*g1(9) &
            + abz*g1(102) &
            + cdz*g1(22) &
            + g1(115)
         vbuf(88) = abx*abz*cdz*g1(4) &
