            + abx*cdz*g1(14) &
            + abx*g1(107) &
            + abz*cdz*g1(10) &
            + abz*g1(103) &
            + cdz*g1(24) &
            + g1(117)
         vbuf(89) = abx*abz*cdz*g1(5) &
            + abx*abz*g1(98) &
            + abx*cdz*g1(15) &
            + abx*g1(108) &
            + abz*cdz*g1(11) &
            + abz*g1(104) &
            + cdz*g1(25) &
            + g1(118)
         vbuf(90) = abx*abz*cdz*g1(6) &
            + abx*abz*g1(99) &
